
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_pi_m06_2x_dl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_pi_m06_2x_dl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.979480340283247e+00, -1.941917769098184e+00, -1.889330594269094e+00, -1.816579079878431e+00, -1.717637005034849e+00, -1.586350039437973e+00, -1.418273207452363e+00, -1.214050846373615e+00, -9.826251225245052e-01, -7.404635974450861e-01, -5.003044347006123e-01, -3.261348353151921e-01, -2.769424946010146e-01, -2.305897323626222e-01, -1.703752333906154e-01, -1.117263974542597e-01, -6.132503907065785e-02, -2.276358988737533e-02, -4.969181545618522e-03, -5.589634772190037e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


